//! B27 — differential: the `arpk-core` model against the native contract on shared traces.
//!
//! One seeded trace drives both implementations. After every operation the test compares
//! accept/reject *and* the resulting state (bucket tokens, venue exposure). A drift between
//! the model the kernel signs with and the contract that enforces on-chain fails here
//! rather than in production.
//!
//! The trace is generated by a tiny xorshift PRNG, so a failure is reproducible from the
//! seed. Step count defaults to 10,000 and can be overridden with `DIFFERENTIAL_STEPS`.

use std::panic::{catch_unwind, AssertUnwindSafe};

use arpk_core::caps::ValueCaps;
use arpk_core::codes::Code;
use arpk_core::eip712::{self, Domain, Receipt as CoreReceipt, ValueAction as CoreAction};
use arpk_core::{class, verdict, Keccak};
use k256::ecdsa::SigningKey;
use near_sdk::json_types::{U128, U64};
use near_sdk::test_utils::VMContextBuilder;
use near_sdk::testing_env;
use near_sdk::{AccountId, NearToken};
use sha3::{Digest, Keccak256};

use near_vault::{AssetCapsDto, ReceiptDto, ValueActionDto, Vault, VenueCapDto};

const MS: u64 = 1_000_000;
const BASE_TS_MS: u64 = 1_762_400_000_000;

// The manifest the contract is registered with. The model is built from the same values.
const PER_CALL_CAP: u128 = 1_000;
const PCT_CAP_BPS: u128 = 10_000;
const APPROVAL_THRESHOLD: u128 = u128::MAX;
const BUCKET_CAPACITY: u128 = 1_000;
const BUCKET_REFILL_PER_S: u128 = 1;
const EXPOSURE_CAP: u128 = 10_000;
/// Funded once at deploy. The contract only raises `ledger` through `deposit()`.
const LEDGER: u128 = 10_000;

// ---------------------------------------------------------------------------
// trace
// ---------------------------------------------------------------------------

/// xorshift64* — no extra dependency, and a failure is reproducible from the seed alone.
struct Rng(u64);

impl Rng {
    fn new(seed: u64) -> Self {
        // Avoid the all-zero fixed point.
        Self(seed.max(1))
    }

    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }

    fn below(&mut self, n: u64) -> u64 {
        self.next() % n
    }
}

enum Op {
    /// Advance the block clock by this many nanoseconds.
    Advance(u64),
    /// Attempt to move this much value.
    Transfer(u128),
}

fn trace(seed: u64, steps: usize) -> Vec<Op> {
    let mut rng = Rng::new(seed);
    let mut ops = Vec::with_capacity(steps);
    for _ in 0..steps {
        // 1 in 5 operations advances the clock, so refill and time windows actually move.
        if rng.below(5) == 0 {
            Op::Advance(rng.below(3_000_000_000) + 1);
        } else {
            // Bias toward the interesting region: around the per-call cap and the bucket
            // capacity, where accept/reject flips.
            let amount = match rng.below(4) {
                0 => rng.below(u64::from(PER_CALL_CAP as u32) * 2) as u128 + 1,
                1 => rng.below(u64::from(BUCKET_CAPACITY as u32) * 2) as u128 + 1,
                2 => rng.below(1_000) as u128 + 1,
                _ => rng.below(u64::from(u32::MAX)) as u128 + 1,
            };
            ops.push(Op::Transfer(amount));
        }
    }
    ops
}

// ---------------------------------------------------------------------------
// model
// ---------------------------------------------------------------------------

/// The model the kernel signs with: `arpk-core`'s own caps and bucket, plus the venue
/// exposure accumulator the contract keeps.
struct Model {
    caps: ValueCaps,
    ledger: u128,
    exposure: u128,
    now_ns: u64,
}

impl Model {
    fn new() -> Self {
        Self {
            caps: ValueCaps::new(
                PER_CALL_CAP,
                PCT_CAP_BPS,
                APPROVAL_THRESHOLD,
                BUCKET_CAPACITY,
                BUCKET_REFILL_PER_S,
            ),
            ledger: LEDGER,
            exposure: 0,
            now_ns: BASE_TS_MS * MS,
        }
    }

    fn advance(&mut self, dt_ns: u64) {
        self.now_ns += dt_ns;
    }

    /// Returns the exact reason code the model denies with, or `None` if it accepts.
    fn transfer(&mut self, amount: u128) -> Option<Code> {
        if let Err(code) = self.caps.check(self.ledger, amount, self.now_ns) {
            return Some(code);
        }
        if self
            .exposure
            .checked_add(amount)
            .map(|e| e > EXPOSURE_CAP)
            .unwrap_or(true)
        {
            return Some(Code::VenueExposureCap);
        }
        self.exposure += amount;
        None
    }

    fn bucket_tokens(&self) -> u128 {
        self.caps.bucket.tokens
    }
}

// ---------------------------------------------------------------------------
// contract harness
// ---------------------------------------------------------------------------

fn asset_dtos() -> Vec<AssetCapsDto> {
    vec![AssetCapsDto {
        asset: "near".to_string(),
        per_call_cap: U128(PER_CALL_CAP),
        pct_cap_bps: U128(PCT_CAP_BPS),
        approval_threshold: U128(APPROVAL_THRESHOLD),
        bucket_capacity: U128(BUCKET_CAPACITY),
        bucket_refill_per_s: U128(BUCKET_REFILL_PER_S),
    }]
}

fn venue_dtos() -> Vec<VenueCapDto> {
    vec![VenueCapDto {
        venue: "venue-a".to_string(),
        exposure_cap: U128(EXPOSURE_CAP),
    }]
}

struct Sha3;
impl Keccak for Sha3 {
    fn keccak256(&self, data: &[u8]) -> [u8; 32] {
        let mut h = Keccak256::new();
        h.update(data);
        h.finalize().into()
    }
}

fn account(s: &str) -> AccountId {
    s.parse().unwrap()
}

fn ctx(predecessor: AccountId, deposit: u128, ts_ms: u64) -> VMContextBuilder {
    let mut ctx = VMContextBuilder::new();
    ctx.current_account_id(account("vault.test.near"));
    ctx.signer_account_id(predecessor.clone());
    ctx.predecessor_account_id(predecessor);
    ctx.block_timestamp(ts_ms * MS);
    ctx.account_balance(NearToken::from_yoctonear(10u128.pow(27)));
    ctx.account_locked_balance(NearToken::from_yoctonear(0));
    ctx.attached_deposit(NearToken::from_yoctonear(deposit));
    ctx
}

struct Contract {
    vault: Vault,
    kernel: SigningKey,
    agent_id: Vec<u8>,
    manifest_hash: [u8; 32],
    next_nonce: u64,
    now_ns: u64,
}

impl Contract {
    fn deploy() -> Self {
        let owner = account("owner.test.near");
        testing_env!(ctx(owner.clone(), 0, BASE_TS_MS).build());
        let mut vault = Vault::new(owner.clone());

        let kernel = SigningKey::from_slice(&[7u8; 32]).unwrap();
        let vk = kernel.verifying_key().to_sec1_point(false);
        let kernel_pub = vk.as_bytes()[1..].to_vec();

        testing_env!(ctx(owner.clone(), 1, BASE_TS_MS).build());
        vault.register_kernel_key(kernel_pub, U64(BASE_TS_MS + 3_600_000));

        let agent_id = Sha3.keccak256(b"agent-diff").to_vec();
        let manifest_hash = Sha3.keccak256(b"manifest-diff");

        testing_env!(ctx(owner, 1, BASE_TS_MS).build());
        vault.register_manifest(
            agent_id.clone(),
            manifest_hash,
            U64(BASE_TS_MS + 3_600_000),
            asset_dtos(),
            venue_dtos(),
        );

        testing_env!(ctx(account("funder.test.near"), LEDGER as u128, BASE_TS_MS).build());
        vault.deposit();

        Self {
            vault,
            kernel,
            agent_id,
            manifest_hash,
            next_nonce: 1,
            now_ns: BASE_TS_MS * MS,
        }
    }

    /// Re-register the manifest. This clears the agent's bucket tokens and venue exposure
    /// back to a fresh state, so each seed starts from the same place.
    ///
    /// It is needed because near-sdk's `testing_env!` mocked storage is process-wide: a
    /// second `deploy()` in the same test would otherwise inherit the first one's used
    /// nonces and fail with `receipt.replayed`.
    fn reset_agent(&mut self) {
        testing_env!(ctx(account("owner.test.near"), 1, BASE_TS_MS).build());
        self.vault.register_manifest(
            self.agent_id.clone(),
            self.manifest_hash,
            U64(BASE_TS_MS + 3_600_000),
            asset_dtos(),
            venue_dtos(),
        );
        self.now_ns = BASE_TS_MS * MS;
    }

    fn advance(&mut self, dt_ns: u64) {
        self.now_ns += dt_ns;
    }

    /// Returns `None` if the contract accepted, or the `ARPK:*` code it panicked with.
    fn transfer(&mut self, amount: u128) -> Option<String> {
        // 16-byte nonce: a fixed prefix plus the step counter.
        let mut nonce = [0u8; 16];
        nonce[8..].copy_from_slice(&self.next_nonce.to_le_bytes());
        self.next_nonce += 1;
        let issued_ms = self.now_ns / MS;
        let expiry_ms = issued_ms + 120_000;

        let action = ValueActionDto {
            chain: "near".to_string(),
            venue: "venue-a".to_string(),
            to: "dest.test.near".to_string(),
            asset: "near".to_string(),
            amount: U128(amount),
            memo_hash: vec![0u8; 32],
        };
        let core_action = CoreAction {
            chain: action.chain.clone(),
            venue: action.venue.clone(),
            to: action.to.clone(),
            asset: action.asset.clone(),
            amount,
            memo_hash: [0u8; 32],
        };

        let domain = {
            let mut buf = Vec::new();
            buf.extend_from_slice(near_sdk::env::chain_id().as_bytes());
            buf.extend_from_slice(near_sdk::env::current_account_id().as_bytes());
            Domain {
                name: "ARPK".to_string(),
                version: "1".to_string(),
                salt: Sha3.keccak256(&buf),
            }
        };
        let action_hash = eip712::hash_value_action(&Sha3, &core_action);
        let receipt = CoreReceipt {
            agent_id: Sha3.keccak256(b"agent-diff"),
            session_id: [9u8; 16],
            class: class::VALUE,
            action_hash,
            manifest_hash: self.manifest_hash,
            context_hash: [0u8; 32],
            verdict: verdict::ALLOW,
            nonce,
            issued_ms,
            expiry_ms,
        };
        let digest = eip712::digest(&Sha3, &domain, &receipt);
        let (sig, recid) = self.kernel.sign_prehash_recoverable(&digest);
        let dto = ReceiptDto {
            agent_id: self.agent_id.clone(),
            session_id: receipt.session_id.to_vec(),
            class: receipt.class,
            action_hash: receipt.action_hash.to_vec(),
            manifest_hash: receipt.manifest_hash.to_vec(),
            context_hash: receipt.context_hash.to_vec(),
            verdict: receipt.verdict,
            nonce: receipt.nonce.to_vec(),
            issued_ms: U64(issued_ms),
            expiry_ms: U64(expiry_ms),
        };

        let predecessor = account("relayer.test.near");
        let ts_ms = self.now_ns / MS;
        testing_env!(ctx(predecessor, 0, ts_ms).build());
        let result = catch_unwind(AssertUnwindSafe(|| {
            let _ = self.vault.execute_value(
                self.agent_id.clone(),
                action,
                dto,
                sig.to_bytes().to_vec(),
                recid.to_byte(),
            );
        }));
        match result {
            Ok(()) => None,
            Err(payload) => {
                let msg = payload
                    .downcast_ref::<String>()
                    .cloned()
                    .or_else(|| payload.downcast_ref::<&str>().map(|s| s.to_string()))
                    .unwrap_or_default();
                // The panic message is `ARPK:<code>` (near-sdk prefixes the file/line).
                Some(msg)
            }
        }
    }

    fn bucket_tokens(&self) -> u128 {
        self.vault.get_agent(self.agent_id.clone()).map_or(0, |a| {
            a.assets.first().map(|x| x.bucket_tokens.0).unwrap_or(0)
        })
    }

    fn exposure(&self) -> u128 {
        self.vault
            .get_agent(self.agent_id.clone())
            .and_then(|a| a.venues.first().map(|v| v.exposure.0))
            .unwrap_or(0)
    }
}

// ---------------------------------------------------------------------------
// the differential
// ---------------------------------------------------------------------------

fn steps() -> usize {
    std::env::var("DIFFERENTIAL_STEPS")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(10_000)
}

#[test]
fn model_and_contract_agree_on_shared_traces() {
    let n = steps();
    eprintln!("differential: {n} steps across 8 seeds");
    // Several seeds, so one unlucky trace is not the only coverage.
    let seeds = [1u64, 2, 3, 4, 5, 6, 7, 8];
    let per = n / seeds.len();

    // One contract instance for the whole run: near-sdk's mocked storage is process-wide,
    // so re-registering the manifest is how each seed gets a clean agent.
    let mut contract = Contract::deploy();

    for seed in seeds {
        let ops = trace(seed, per);
        let mut model = Model::new();
        contract.reset_agent();

        for (i, op) in ops.iter().enumerate() {
            match *op {
                Op::Advance(dt) => {
                    model.advance(dt);
                    contract.advance(dt);
                }
                Op::Transfer(amount) => {
                    let model_code = model.transfer(amount);
                    let contract_msg = contract.transfer(amount);

                    // Compare accept/reject first.
                    match (model_code, &contract_msg) {
                        (None, None) => {}
                        (Some(code), Some(msg)) => {
                            assert!(
                                msg.contains(code.as_str()),
                                "seed {seed} step {i}: model denied {} but contract said {msg}",
                                code.as_str()
                            );
                        }
                        (None, Some(msg)) => panic!(
                            "seed {seed} step {i}: model accepted amount {amount} but the contract denied it with {msg}"
                        ),
                        (Some(code), None) => panic!(
                            "seed {seed} step {i}: model denied {} but the contract accepted amount {amount}",
                            code.as_str()
                        ),
                    }

                    // Then compare the resulting state.
                    assert_eq!(
                        model.bucket_tokens(),
                        contract.bucket_tokens(),
                        "seed {seed} step {i}: bucket tokens diverged after amount {amount}"
                    );
                    assert_eq!(
                        model.exposure,
                        contract.exposure(),
                        "seed {seed} step {i}: venue exposure diverged after amount {amount}"
                    );
                }
            }
        }
    }
}
